import os, re
root='/app'
runs=set()
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f=='recovered_passwords.txt' or f.endswith('.py'): continue
        p=os.path.join(dp,f)
        try:
            data=open(p,'rb').read()
        except Exception:
            continue
        for m in re.finditer(rb'[A-Z0-9]+', data):
            s=m.group().decode()
            if len(s)>=3:
                runs.add(s)
starts=[r for r in runs if r.startswith('8XD')]
ends=[r for r in runs if r.endswith('W54')]
print('start fragments (8XD..):', starts)
print('end fragments (...W54):  ', ends)
cands=set()
# single full runs
for r in runs:
    if len(r)==23 and r.startswith('8XD') and r.endswith('W54'):
        cands.add(r)
# fragment pairs (start + end)
for s in starts:
    for e in ends:
        pw=s+e
        if len(pw)==23 and pw.startswith('8XD') and pw.endswith('W54') and re.fullmatch(r'[A-Z0-9]+',pw):
            cands.add(pw)
cands=sorted(cands)
print('candidates:', cands)
with open('/app/recovered_passwords.txt','w') as out:
    for c in cands:
        out.write(c+'\n')
print('wrote', len(cands), 'password(s) to /app/recovered_passwords.txt')
